  testRuns: z.object({
    gold: z.array(z.string().min(1)).default([]),
    adversarial: z.array(z.string().min(1)).default([]),
    consistency: z.array(z.string().min(1)).default([]),
  }).strict().default({gold: [], adversarial: [], consistency: []}),
}).strict().superRefine((procedure, context) => {
