107	  it("blocks a scenario whose lever has no registered assumption instead of filling zero, and blocks the run when a minimum scenario is blocked", () => {
108	    const base = camil();
109	    const noHaircut = declareScenarios({...base, assumptions: base.assumptions.filter((assumption) => assumption.role !== "ebitda_haircut")});
110	    expect(by(noHaircut, "adverse").state).toBe("blocked");
111	    expect(by(noHaircut, "adverse").block_reasons[0]).toMatch(/EBITDA haircut but none is registered; the haircut is not filled with zero/);
112	    expect(by(noHaircut, "adverse").results.pro_forma.leverage).toBeNull();
113	    expect(noHaircut.state).toBe("blocked");
114	    expect(noHaircut.block_reasons[0]).toMatch(/^adverse:/);
115	    const noRolloverAssumption = declareScenarios({...base, assumptions: base.assumptions.filter((assumption) => assumption.role !== "rollover")});
116	    expect(by(noRolloverAssumption, "base").state).toBe("blocked");
117	    expect(by(noRolloverAssumption, "no_rollover").state).toBe("partial");
118	    const halfRefinancing = declareScenarios({...base, assumptions: [...base.assumptions, {key: "refi.new", role: "new_debt", period: null, value: "300000", unit: "BRL thousand", origin: "user_range", rationale: "nova dívida declarada", asOf, anchor: user(), confidence: "low"}], scenarios: [...base.scenarios, {id: "refi", label: "Refinanciamento", rolloverAllowed: false, usesRefinancing: true}]});
119	    expect(by(halfRefinancing, "refi").state).toBe("blocked");
120	    expect(halfRefinancing.state).toBe("partial");
121	  });
122	
123	  it("never repeats CFADS across periods: a period without its own CFADS leaves the cover unmeasured", () => {
124	    const base = camil();
125	    const result = declareScenarios({...base, assumptions: base.assumptions.filter((assumption) => assumption.key !== "cfads.2027-28.range")});
126	    expect(by(result, "base").results.liquidity).toBeNull();
127	    expect(by(result, "base").uncovered_terms.some((term) => term.id === "cfads:2027/28" && /no figure is repeated from another period/.test(term.reason))).toBe(true);
128	    expect(by(result, "base").state).toBe("partial");
129	  });
130	
131	  it("measures headroom only against an applicable, resolved and comparable limit with a comparable EBITDA", () => {
132	    const base = camil();
133	    const resolved: ScenarioInput = {...base, covenant: {...base.covenant!, state: "resolved", comparability: "comparable", tier: {applicability: "applicable", condition: "quitação ordinária dos CRA provada (hipótese de teste)"}}, position: {...base.position, ltmEbitda: {...base.position.ltmEbitda!, comparability: "comparable", comparabilityReasons: []}}};
134	    const result = declareScenarios(resolved);
135	    expect(by(result, "base").results.headroom?.absolute).toBe(d("4").minus(d("4228477").div("895864").toDecimalPlaces(8)).toDecimalPlaces(8).toFixed());
136	    expect(by(result, "base").results.headroom?.within_limit).toBe(false);
137	    expect(by(result, "base").results.headroom?.note).toMatch(/scenario reading before the measurement of 2027-02-28/);
138	    const inapplicable = declareScenarios({...resolved, covenant: {...resolved.covenant!, tier: {applicability: "not_applicable", condition: "degrau posterior"}}});
139	    expect(by(inapplicable, "base").results.headroom).toBeNull();
